export const byTag = (tag: string) =>
  WAREHOUSE_PHOTOS.filter((photo) => photo.tags.includes(tag));

export const bySlug = (slug: string) =>
  WAREHOUSE_PHOTOS.find((photo) => photo.src === `/warehouse/${slug}.webp`);
